-- AbiHub Tamil Nadu locality import
-- Source: uploaded tamil_nadu_villages.csv
-- Source rows: 18,710; unique district/village pairs: 18,127
-- Existing schema used: location_states, location_districts, location_areas (BIGINT IDs).
-- CSV taluk, pincode, village code and native-name columns are not stored because
-- the existing location_areas table only has district_id, name and is_active.
-- District aliases mapped to existing schema names: The Nilgiris->Nilgiris,
-- Thiruvallur->Tiruvallur, Thiruvarur->Tiruvarur, Thoothukkudi->Thoothukudi.

BEGIN;

-- Ensure Tamil Nadu state exists.
INSERT INTO public.location_states (name, is_active)
SELECT 'Tamil Nadu', TRUE
WHERE NOT EXISTS (
  SELECT 1 FROM public.location_states WHERE lower(name) = 'tamil nadu'
);

-- Ensure all 38 district rows exist under Tamil Nadu.
WITH district_data(name) AS (VALUES
  ('Ariyalur'),
  ('Chengalpattu'),
  ('Chennai'),
  ('Coimbatore'),
  ('Cuddalore'),
  ('Dharmapuri'),
  ('Dindigul'),
  ('Erode'),
  ('Kallakurichi'),
  ('Kancheepuram'),
  ('Kanniyakumari'),
  ('Karur'),
  ('Krishnagiri'),
  ('Madurai'),
  ('Mayiladuthurai'),
  ('Nagapattinam'),
