  ('Perambalur'),
  ('Pudukkottai'),
  ('Ramanathapuram'),
  ('Ranipet'),
  ('Salem'),
  ('Sivaganga'),
  ('Tenkasi'),
  ('Thanjavur'),
  ('Theni'),
  ('Thoothukudi'),
  ('Tiruchirappalli'),
  ('Tirunelveli'),
  ('Tirupathur'),
  ('Tiruppur'),
  ('Tiruvallur'),
  ('Tiruvannamalai'),
  ('Tiruvarur'),
  ('Vellore'),
  ('Viluppuram'),
  ('Virudhunagar')
)
INSERT INTO public.location_districts (state_id, name, is_active)
SELECT s.id, d.name, TRUE
FROM district_data d
CROSS JOIN public.location_states s
WHERE lower(s.name) = 'tamil nadu'
  AND NOT EXISTS (
    SELECT 1 FROM public.location_districts existing
    WHERE existing.state_id = s.id
      AND lower(existing.name) = lower(d.name)
  );

