INSERT INTO public.location_areas (district_id, name, is_active)
SELECT d.id, l.area_name, TRUE
FROM (
  SELECT DISTINCT ON (lower(district_name), lower(area_name))
         district_name, area_name
  FROM locality_data
  ORDER BY lower(district_name), lower(area_name), area_name
) l
JOIN public.location_districts d
  ON lower(d.name) = lower(l.district_name)
JOIN public.location_states s
  ON s.id = d.state_id AND lower(s.name) = 'tamil nadu'
WHERE NOT EXISTS (
  SELECT 1
  FROM public.location_areas existing
  WHERE existing.district_id = d.id
    AND lower(existing.name) = lower(l.area_name)
);

COMMIT;

-- Verification: rows per district.
SELECT d.name AS district, COUNT(a.id) AS area_count
FROM public.location_districts d
JOIN public.location_states s ON s.id = d.state_id
LEFT JOIN public.location_areas a ON a.district_id = d.id AND a.is_active = TRUE
WHERE lower(s.name) = 'tamil nadu'
GROUP BY d.name
ORDER BY d.name;

-- Overall Tamil Nadu area count.
SELECT COUNT(*) AS tamil_nadu_area_count
FROM public.location_areas a
JOIN public.location_districts d ON d.id = a.district_id
JOIN public.location_states s ON s.id = d.state_id
WHERE lower(s.name) = 'tamil nadu' AND a.is_active = TRUE;